MODELAGEM_LOGICO_ALGORITMA.CODIGO_FONTE:
if (temperatura < 20.0) {
  controlarLED(false, false, true);
  cor = "AZUL";
  estado = "FRIO";
}
else if (temperatura <= 30.0) {
  controlarLED(true, true, false);
  cor = "AMARELO";
  estado = "NORMAL";
}
else {
  controlarLED(true, false, false);
  cor = "VERMELHO";
  estado = "QUENTE";
}
